command:
$ErrorActionPreference='Stop'
$repo=[Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
if([string]::IsNullOrWhiteSpace($repo)){$repo=$env:GITHUB_WORKSPACE}
$branch='test-494-dcoir-production-acceptance-post497'
$ref=('refs/heads/'+$branch)
$before=(git -C $repo ls-remote --heads origin $ref)
if([string]::IsNullOrWhiteSpace(($before -join ''))){Write-Host 'BRANCH_ALREADY_ABSENT=true';exit 0}
git -C $repo push origin --delete $branch
if($LASTEXITCODE -ne 0){throw 'branch deletion failed'}
$after=(git -C $repo ls-remote --heads origin $ref)
if(-not [string]::IsNullOrWhiteSpace(($after -join ''))){throw 'branch still exists after deletion'}
Write-Host 'BRANCH_DELETED=true'
